// Captação – Coleta: funções puras (testadas com node --test).
// O gerador embute este arquivo no nó Code, sem o bloco de exportação do Node no fim.
function decodeEnt(s) {
  return String(s || '').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'").replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&#(\d+);/g, function (m, n) { return String.fromCharCode(Number(n)); });
}
function limpaTexto(s) { return decodeEnt(String(s || '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim(); }
function partesUrl(u) {
  var m = String(u || '').trim().match(/^(https?):\/\/([^\/?#]+)([^?#]*)(\?[^#]*)?(#.*)?$/i);
  if (!m) return null;
  return { proto: m[1].toLowerCase(), host: m[2].toLowerCase(), path: m[3] || '/', query: (m[4] || '').slice(1) };
}
function limpaCaminho(p) {
  var seg = p.split('/'), out = [];
  for (var i = 0; i < seg.length; i++) {
    var s = seg[i];
    if (s === '..') { if (out.length > 1) out.pop(); }
    else if (s !== '.') out.push(s);
  }
  var r = out.join('/');
  return r.charAt(0) === '/' ? r : '/' + r;
}
function resolveUrl(href, base) {
  href = String(href || '').trim();
  if (/^https?:\/\//i.test(href)) return href;
  var b = partesUrl(base); if (!b) return '';
  if (/^\/\//.test(href)) return b.proto + ':' + href;
  if (/^[a-z][a-z0-9+.-]*:/i.test(href)) return '';
  if (href.charAt(0) === '/') return b.proto + '://' + b.host + href;
  if (href.charAt(0) === '?') return b.proto + '://' + b.host + b.path + href;
  var dir = b.path.replace(/[^\/]*$/, '');
  var hp = href.split(/(?=[?#])/);
  return b.proto + '://' + b.host + limpaCaminho(dir + hp[0]) + hp.slice(1).join('');
}
var RASTREIO = /^(utm_[a-z]+|fbclid|gclid|mc_cid|mc_eid|_ga|_gl|ref|x-amz-[a-z0-9-]+|cvid)$/i;
function normalizaUrl(u) {
  var p = partesUrl(u); if (!p) return '';
  var host = p.host.replace(/:(80|443)$/, '');
  var pares = p.query ? p.query.split('&').filter(function (kv) { if (!kv) return false; var k = kv.split('=')[0]; try { k = decodeURIComponent(k); } catch (e) {} return !RASTREIO.test(k); }) : [];
  pares.sort();
  var path = p.path.replace(/ /g, '%20');
  if (path.length > 1 && path.charAt(path.length - 1) === '/') path = path.slice(0, -1);
  return p.proto + '://' + host + path + (pares.length ? '?' + pares.join('&') : '');
}
function hostDe(u) { var p = partesUrl(u); return p ? p.host : ''; }
function semAcento(t) { return String(t || '').normalize('NFD').replace(/[̀-ͯ]/g, ''); }
function hashTexto(str) {
  var h1 = 0xdeadbeef, h2 = 0x41c6ce57, h3 = 0x9e3779b9, h4 = 0x85ebca6b;
  for (var i = 0; i < str.length; i++) {
    var ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677);
    h3 = Math.imul(h3 ^ ch, 2246822507); h4 = Math.imul(h4 ^ ch, 3266489909);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  h3 = Math.imul(h3 ^ (h3 >>> 16), 2246822507) ^ Math.imul(h4 ^ (h4 >>> 13), 3266489909);
  h4 = Math.imul(h4 ^ (h4 >>> 16), 2246822507) ^ Math.imul(h3 ^ (h3 >>> 13), 3266489909);
  function hx(n) { return ('00000000' + (n >>> 0).toString(16)).slice(-8); }
  return hx(h1) + hx(h2) + hx(h3) + hx(h4);
}
// Datas: coluna date do n8n recebe ISO completo ou null (nunca string vazia).
function isoDoDia(v) {
  var m = String(v || '').match(/^(\d{4}-\d{2}-\d{2})/);
  return m ? m[1] + 'T12:00:00.000Z' : null;
}
function diaDe(v) { var m = String(v || '').match(/^(\d{4}-\d{2}-\d{2})/); return m ? m[1] : ''; }
