}
var MESES_EN = { january: 1, february: 2, march: 3, april: 4, may: 5, june: 6, july: 7, august: 8, september: 9, october: 10, november: 11, december: 12 };
function dataPorExtenso(t) {
  var m = String(t || '').match(/(\d{1,2})\s+([A-Za-z]+),?\s+(\d{4})/);
  var mes = m && MESES_EN[m[2].toLowerCase()];
  if (!mes) return null;
  return m[3] + '-' + ('0' + mes).slice(-2) + '-' + ('0' + m[1]).slice(-2);
}
function extrairLinks(html, base) {
  var h = String(html || '');
  h = h.replace(/<(script|style|noscript)\b[\s\S]*?<\/\1>/gi, ' ');
  h = h.replace(/<(nav|header|footer)\b[\s\S]*?<\/\1>/gi, ' ');
  var re = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi, m, out = [], vistos = {};
  var baseNorm = normalizaUrl(base);
  while ((m = re.exec(h))) {
    var attrs = m[1];
    var hm = attrs.match(/href\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (!hm) continue;
    var href = decodeEnt((hm[2] || hm[3] || hm[4] || '').trim());
    if (!href || /^(#|javascript:|mailto:|tel:)/i.test(href)) continue;
    var abs = resolveUrl(href, base);
    if (!abs) continue;
    var url = normalizaUrl(abs);
    if (!url || url === baseNorm) continue;
    if (NAO_URL.test(url)) continue;
    var pu = partesUrl(url), pb = partesUrl(base);
    if (pu && pb && pu.host === pb.host && pu.path === pb.path) continue; // só mudou a query (paginação)
    if (HOST_FORA.test(hostDe(url))) continue;
    var texto = limpaTexto(m[2]);
    var prazoTxt = null;
    // Listas que marcam a situação no próprio link (CCAC): "Closed on: ..." = encerrada; "Open Closing: ..." traz o prazo.
    if (/^closed\b/i.test(texto)) continue;
    var sm = texto.match(/^open\s+closing:?\s*(\d{1,2}\s+[A-Za-z]+,?\s+\d{4})\s*/i);
    if (sm) { prazoTxt = dataPorExtenso(sm[1]); texto = texto.slice(sm[0].length).trim(); }
    var tm = attrs.match(/title\s*=\s*"([^"]*)"/i);
    if ((!texto || GENERICO.test(texto)) && tm && !GENERICO.test(limpaTexto(tm[1]))) texto = limpaTexto(tm[1]);
