}

// ---------- finep: JSON público (o campo "situacao" mente; vale a data) ----------
function extrairFinep(corpo, hojeIso) {
  var d = typeof corpo === 'string' ? JSON.parse(corpo) : corpo;
  var out = [];
  (d.items || []).forEach(function (it) {
    // Prazo efetivo: prazoProposto quando existe; senão a vigência. Item sem nenhuma data não é aproveitável.
    var prazo = diaDe(it.prazoProposto) || diaDe(it.vigenciaFim);
    if (!prazo || prazo < hojeIso) return;
    if (!it.id || !it.titulo) return;
    var partes = [it.descricaoRawText || limpaTexto(it.descricao), arr(it.publicoAlvo).map(nomeDe).join(', '), nomeDe(it.tipoDeOportunidade), nomeDe(it.temaPrincipal), String(it.tema || ''), nomeDe(it.regiao)];
    out.push({
      url: 'https://www.finep.gov.br/e/chamada-publica/222684/' + it.id,
      titulo: limpaTexto(it.titulo).slice(0, 300),
      prazo_fonte: isoDoDia(prazo),
      texto_fonte: partes.filter(Boolean).join('\n').slice(0, 8000)
    });
  });
  return out;
}

// ---------- transferegov: programas por id_programa ----------
function extrairTransferegov(corpos, hojeIso) {
  var lista = [], paginas = 1;
  arr(corpos).forEach(function (c) {
    var d = typeof c === 'string' ? JSON.parse(c) : c;
    lista = lista.concat((d && d.data) || []);
    paginas = Math.max(paginas, (d && d.total_pages) || 1);
  });
  var porId = {}, ordem = [];
  lista.forEach(function (p) {
    var k = p.id_programa; if (!k) return;
    if (!porId[k]) { porId[k] = { linhas: [], ufs: {} }; ordem.push(k); }
    porId[k].linhas.push(p);
    if (p.uf_programa) porId[k].ufs[p.uf_programa] = 1;
  });
  var out = [];
  ordem.forEach(function (k) {
    var o = porId[k], p = o.linhas[0];
    if (Object.keys(o.ufs).length && !o.ufs.DF) return;
    var fim = diaDe(p.dt_prog_fim_receb_prop);
    if (fim && fim < hojeIso) return;
    var quals = o.linhas.map(function (x) { return x.qualificacao_proposta; }).filter(function (v, i, a) { return v && a.indexOf(v) === i; });
    var nats = o.linhas.map(function (x) { return x.natureza_juridica_programa; }).filter(function (v, i, a) { return v && a.indexOf(v) === i; });
    var texto = [
      'Programa federal no Transferegov',
      'Programa: ' + (p.nome_programa || ''),
      'Órgão: ' + (p.desc_orgao_sup_programa || '') + ' / ' + (p.orgao_executor || ''),
      'Qualificação das propostas: ' + quals.join('; '),
      'Natureza jurídica de quem pode propor: ' + nats.join('; '),
      'Chamamento público: ' + (o.linhas.some(function (x) { return x.chamamento_projeto === 'SIM'; }) ? 'SIM' : 'NÃO'),
      'Recebimento de propostas: de ' + (p.dt_prog_ini_receb_prop || 'não informado') + ' até ' + (p.dt_prog_fim_receb_prop || 'não informado'),
      'Descrição: ' + limpaTexto(p.descricao),
      'Observação: ' + limpaTexto(p.observacao),
      'Critérios de seleção: ' + limpaTexto(p.criterios_de_selecao)
    ].join('\n').slice(0, 8000);
    out.push({
      url: 'https://api-publica.transferegov.gestao.gov.br/discricionarias/todos-programas?id_programa=' + k,
      titulo: (String(p.nome_programa || 'Programa ' + k).trim() + ' - ' + String(p.desc_orgao_sup_programa || '').trim()).slice(0, 300),
      prazo_fonte: isoDoDia(fim),
      texto_fonte: texto
    });
  });
  return { itens: out, paginas: paginas };
}

// ---------- ue: Funding & Tenders (SEDIA), POST multipart ----------
var UE_BASE = 'https://api.tech.ec.europa.eu/search-api/prod/rest/search';
// [termo, páginas de 100]: a API devolve no máximo 100 por página; termos largos precisam de mais de uma.
var UE_TERMOS = [['agriculture', 2], ['agri-food', 2], ['food safety', 3], ['traceability', 1], ['soil', 1], ['methane', 1], ['climate', 3], ['freight', 1], ['road transport', 2], ['logistics', 1], ['artificial intelligence', 3]];
// A busca por texto pega o corpo inteiro do tópico; só ficam os que citam o assunto no título, resumo ou palavras-chave.
var UE_RELEVANCIA = /(agricultur|agri-?food|\bfarm|\bcrops?\b|\bsoils?\b|\bfood\b|livestock|methane|climate|freight|transport|logistic|\broad\b|artificial intelligence|\bAI\b|machine learning|traceab|supply chain)/i;
var UE_QUERY = { bool: { must: [{ terms: { type: ['1', '2', '8'] } }, { terms: { status: ['31094501', '31094502'] } }] } };
// Corpo multipart montado à mão: a API exige Content-Type: application/json em cada parte, o que o
// formData do nó HTTP Request não permite. O nó envia este texto cru, com o boundary no cabeçalho.
var UE_BOUNDARY = '----ModalCaptacaoBoundary7MA4YWxkTrZu0gW';
function corpoMultipartUe() {
  var parte = function (nome, json) { return '--' + UE_BOUNDARY + '\r\nContent-Disposition: form-data; name="' + nome + '"\r\nContent-Type: application/json\r\n\r\n' + json + '\r\n'; };
  return parte('query', JSON.stringify(UE_QUERY)) + parte('languages', JSON.stringify(['en'])) + '--' + UE_BOUNDARY + '--\r\n';
}
function urlBuscaUe(urlFonte, termo, pagina) {
  var base = /search-api/.test(String(urlFonte || '')) ? String(urlFonte).split('?')[0] : UE_BASE;
  return base + '?apiKey=SEDIA&text=' + encodeURIComponent(termo) + '&pageSize=100&pageNumber=' + (pagina || 1);
}
function unico(v) { return arr(v)[0]; }
function urlPortalUe(url, identificador) {
  var u = String(url || '');
  var m = u.match(/\/data\/topicDetails\/([^\/?#]+?)(\.json)?$/i);
  // topicDetails/<ID>.json é o arquivo de dados; o endereço para gente ler é a página do portal.
  if (m && /^[A-Za-z0-9-]+$/.test(m[1]) && !/^\d+COMPETITIVE_CALL/i.test(m[1])) return 'https://ec.europa.eu/info/funding-tenders/opportunities/portal/screen/opportunities/topic-details/' + m[1];
  return u;
}
function extrairUe(corpos, hojeIso) {
  var out = [], vistos = {};
  arr(corpos).forEach(function (c) {
    var d = typeof c === 'string' ? JSON.parse(c) : c;
    (d.results || []).forEach(function (r) {
      var m = r.metadata || {};
      var prazos = arr(m.deadlineDate).map(diaDe).filter(function (x) { return x && x >= hojeIso; }).sort();
      if (!prazos.length) return;
      var url = urlPortalUe(r.url || unico(m.url), unico(m.identifier));
      var chaveUrl = normalizaUrl(url);
      if (!chaveUrl || vistos[chaveUrl]) return;
      vistos[chaveUrl] = 1;
      var titulo = limpaTexto(unico(m.title) || r.summary || unico(m.identifier));
      var palavras = arr(m.keywords).map(function (k) { try { var j = JSON.parse(k); return Array.isArray(j) ? j.join(', ') : String(k); } catch (e) { return String(k); } }).join(', ');
      if (!UE_RELEVANCIA.test(titulo + ' ' + limpaTexto(r.summary) + ' ' + palavras + ' ' + (unico(m.identifier) || ''))) return;
      var texto = [
        'Identificador: ' + (unico(m.identifier) || ''),
        'Título: ' + titulo,
        'Resumo: ' + limpaTexto(r.summary),
        'Programa-quadro: ' + (unico(m.frameworkProgramme) || ''),
        'Tipos de ação: ' + arr(m.typesOfAction).join(', '),
        'Prazos: ' + prazos.join(', '),
        'Palavras-chave: ' + palavras,
        'Descrição: ' + limpaTexto(arr(m.description).join(' '))
      ].join('\n').slice(0, 8000);
      out.push({ url: url, titulo: titulo.slice(0, 300), prazo_fonte: isoDoDia(prazos[0]), texto_fonte: texto });
    });
  });
  return out;
}

// ---------- wpjson (EMBRAPII): posts recentes que falam de chamada ----------
var ASSUNTO_WP = /(chamada|edital|editais|credenciamento|sele[cç][aã]o|chamamento)/i;
function extrairWpjson(corpo, hojeIso, dias) {
  var posts = typeof corpo === 'string' ? JSON.parse(corpo) : corpo;
  var limite = new Date(hojeIso + 'T00:00:00Z'); limite.setUTCDate(limite.getUTCDate() - (dias || 120));
  var limIso = limite.toISOString().slice(0, 10);
  var out = [];
  (Array.isArray(posts) ? posts : []).forEach(function (p) {
    var dia = diaDe(p.date || p.date_gmt);
    if (!dia || dia < limIso) return;
    var titulo = limpaTexto(p.title && p.title.rendered);
    var excerpt = limpaTexto(p.excerpt && p.excerpt.rendered);
    if (!p.link || !titulo) return;
    if (!ASSUNTO_WP.test(semAcento(titulo + ' ' + excerpt))) return;
    out.push({
      url: p.link, titulo: titulo.slice(0, 300), prazo_fonte: null,
      texto_fonte: (excerpt + '\n' + limpaTexto(p.content && p.content.rendered)).trim().slice(0, 8000)
    });
  });
  return out;
}

// ---------- requisições por fonte ----------
// agora: { ano, ehSegunda, manual }. Fontes semanais só às segundas; execução manual lê todas.
function montarRequisicoes(fontes, agora) {
  var out = [];
  (fontes || []).forEach(function (f) {
    if (!f || !f.url || f.ativa !== true) return;
    if (f.frequencia === 'semanal' && !agora.ehSegunda && !agora.manual) return;
    var urlFonte = String(f.url).split('{ano}').join(String(agora.ano));
    var base = { fonte_id: f.id, fonte: f.nome, tipo: f.tipo, abrangencia: f.abrangencia || '', url_fonte: urlFonte };
    if (f.tipo === 'transferegov') {
      ['EXPIRACAO_PROG_DISTANTE', 'EXPIRACAO_PROG_PROX', 'EXPIRACAO_PROG_MUITO_PROX'].forEach(function (e) {
        var sep = urlFonte.indexOf('?') >= 0 ? '&' : '?';
        out.push(Object.assign({}, base, { metodo: 'GET', req_url: urlFonte + sep + 'expiracao_prog_prop_voluntaria=' + e + '&uf_programa=DF&tamanho_da_pagina=200' }));
      });
    } else if (f.tipo === 'ue') {
      UE_TERMOS.forEach(function (tp) {
        for (var pg = 1; pg <= tp[1]; pg++) {
          out.push(Object.assign({}, base, { metodo: 'POST', req_url: urlBuscaUe(urlFonte, tp[0], pg), corpo_multipart: corpoMultipartUe(), content_type: 'multipart/form-data; boundary=' + UE_BOUNDARY, pagina: pg, paginas: tp[1] }));
        }
      });
    } else if (f.tipo === 'wpjson') {
      var sepw = urlFonte.indexOf('?') >= 0 ? '&' : '?';
      out.push(Object.assign({}, base, { metodo: 'GET', req_url: /per_page=/.test(urlFonte) ? urlFonte : urlFonte + sepw + 'per_page=100' }));
    } else {
      out.push(Object.assign({}, base, { metodo: 'GET', req_url: urlFonte }));
    }
  });
  return out;
}

// ---------- uma resposta -> candidatos ----------
function extrairPorTipo(tipo, corpo, ctx) {
  var hoje = ctx.hojeIso;
  if (tipo === 'finep') return { itens: extrairFinep(corpo, hoje), aviso: '' };
  if (tipo === 'transferegov') {
    var r = extrairTransferegov(corpo, hoje);
    return { itens: r.itens, aviso: r.paginas > 1 ? 'API com ' + r.paginas + ' páginas; só a primeira foi lida' : '' };
  }
  if (tipo === 'ue') {
    var du = typeof corpo === 'string' ? JSON.parse(corpo) : corpo;
    var cheia = ctx.pagina && ctx.pagina === ctx.paginas && (du.totalResults || 0) > ctx.pagina * 100;
    return { itens: extrairUe(du, hoje), aviso: cheia ? 'busca da UE com mais de ' + ctx.pagina * 100 + ' resultados para um termo; o excedente não foi lido' : '' };
  }
  if (tipo === 'wpjson') return { itens: extrairWpjson(corpo, hoje, ctx.dias), aviso: '' };
  return { itens: extrairLinks(corpo, ctx.urlFonte), aviso: '' };
}

// Só endereços públicos: nada de IP, nome sem domínio (contêineres do servidor), localhost, .local/.internal
// nem *.modal.org.br (no kitty esses nomes apontam para o proxy interno). Um link plantado numa página de
// terceiro não pode levar o robô a ler serviço interno.
function enderecoPublico(u) {
  var m = String(u || '').trim().match(/^https?:\/\/([^\/?#:@]+)(:(?:80|443))?([\/?#]|$)/i);
  if (!m) return false;
  var h = m[1].toLowerCase().replace(/\.$/, '');
  // Nome de domínio comum: rótulos só com letras, números e hífen, terminando em domínio de letras
  // (recusa IP em qualquer grafia, como 0x7f.0.0.1 ou 0177.1, barra invertida e %).
  if (!/^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$/.test(h)) return false;
  if (/(^|\.)(localhost|local|internal|lan|home|arpa)$/.test(h)) return false;
  if (/(^|\.)modal\.org\.br$/.test(h)) return false;
  return true;
}

// Tabela de oportunidades vazia no início da execução => esta coleta é a linha de base.
function ehLinhaBase(linhasExistentes) {
  return !(linhasExistentes || []).some(function (r) { return r && r.chave; });
}

// Monta as linhas novas a gravar (só chaves ainda inexistentes; hash do endereço normalizado).
function linhasNovas(cands, existentes, o) {
  var novas = [], vistos = new Set();
  (cands || []).forEach(function (c) {
    if (!enderecoPublico(c.url)) return;
    var chave = hashTexto(normalizaUrl(c.url));
    if (existentes.has(chave) || vistos.has(chave)) return;
    vistos.add(chave);
    novas.push({
      chave: chave, titulo: c.titulo, url: c.url, fonte: o.fonte, data_captura: o.agoraIso,
      linha_base: o.linhaBase === true, texto_fonte: c.texto_fonte || '', prazo_fonte: c.prazo_fonte || null,
      situacao_triagem: 'pendente', tentativas: 0, motivo: ''
    });
  });
  return novas;
}

// Resumo por fonte para atualizar ultima_coleta / ultimo_status / itens_ultima.
function statusDasFontes(resultados, agoraIso) {
  var porFonte = {}, ordem = [];
  (resultados || []).forEach(function (j) {
    if (!j || !j.fonte_id) return;
    var f = porFonte[j.fonte_id];
    if (!f) { f = porFonte[j.fonte_id] = { id: j.fonte_id, erros: [], avisos: [], encontrados: 0, chaves: {}, ok: 0 }; ordem.push(j.fonte_id); }
    if (j.erro) f.erros.push(j.erro); else f.ok++;
    if (j.aviso && f.avisos.indexOf(j.aviso) < 0) f.avisos.push(j.aviso);
    f.encontrados += j.encontrados || 0;
    (j.novos || []).forEach(function (n) { f.chaves[n.chave] = 1; });
  });
  return ordem.map(function (id) {
    var f = porFonte[id], novos = Object.keys(f.chaves).length, st;
    if (f.ok === 0) st = 'erro: ' + f.erros.join(' | ');
    else if (f.encontrados === 0) st = 'alerta: leitura ok, nenhum candidato';
    else st = 'ok: ' + f.encontrados + ' candidatos, ' + novos + ' novos';
    if (f.ok > 0 && f.erros.length) st += ' (falhas parciais: ' + f.erros.join(' | ') + ')';
    if (f.avisos.length) st += ' (' + f.avisos.join('; ') + ')';
    return { id: id, ultima_coleta: agoraIso, ultimo_status: st.slice(0, 500), itens_ultima: novos };
  });
}


